            line = re.sub(r'\b(https?)://([^/ \n\?]+)(/[^ \n\?]*)?(\?[^ \n]*)?', highlight_url, line)

        # 3. Pointers, UUIDs, IPs (Hex things)
        hex_enabled = any(g in self.enabled for g in ["pointers", "uuids", "ip-addresses"])
        if hex_enabled:
            def color_hex(text, is_pointer=False):
                res = ""
