    import argparse
    parser = argparse.ArgumentParser(description="A log file highlighter", add_help=False)
    parser.add_argument("file", nargs="?", help="Filepath")
    parser.add_argument("-f", "--follow", action="store_true", help="Follow the contents of a file")
    parser.add_argument("-p", "--print", action="store_true", help="Print the output to stdout")
    parser.add_argument("-e", "--exec", help="Run command and view the output in a pager")
    parser.add_argument("--highlight", action="append", help="Highlights in the form color:word1,word2")
    parser.add_argument("--enable", help="Enable specific highlighters")
    parser.add_argument("--disable", help="Disable specific highlighters")
    parser.add_argument("--disable-builtin-keywords", action="store_true", help="Disable the highlighting of all builtin keyword groups")
    parser.add_argument("--pager", help="Override the default pager")
    parser.add_argument("-h", "--help", action="help", help="Print help")

    args = parser.parse_args()

    custom_highlights = []
    if args.highlight:
        for h in args.highlight:
            color, words = h.split(":", 1)
            custom_highlights.append((color, words.split(",")))

    enabled = args.enable.split(",") if args.enable else None
    disabled = args.disable.split(",") if args.disable else None

    highlighter = Highlighter(enabled=enabled, disabled=disabled, disable_builtin=args.disable_builtin_keywords, custom_highlights=custom_highlights)

    if args.exec:
        # Run command and highlight output
        process = subprocess.Popen(args.exec, shell=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
        if args.print:
            for line in process.stdout:
                print(highlighter.highlight_line(line), end="")
        else:
            # Pager logic
            run_with_pager(process.stdout, highlighter, args.pager)
        return

    if args.file:
        if args.follow:
            # Similar to tail -f
            process = subprocess.Popen(["tail", "-f", args.file], stdout=subprocess.PIPE, text=True)
            if args.print:
                for line in process.stdout:
                    print(highlighter.highlight_line(line), end="")
            else:
                run_with_pager(process.stdout, highlighter, args.pager)
        else:
            with open(args.file, "r") as f:
                if args.print:
                    for line in f:
                        print(highlighter.highlight_line(line), end="")
                else:
                    run_with_pager(f, highlighter, args.pager)
    elif not sys.stdin.isatty():
        # Read from stdin
        if args.print or True: # Stdin always prints according to man page
            for line in sys.stdin:
                print(highlighter.highlight_line(line), end="")
    else:
        parser.print_help()

def run_with_pager(input_stream, highlighter, custom_pager):
    # Create temp file
    with tempfile.NamedTemporaryFile(mode="w", delete=False) as tmp:
        tmp_path = tmp.name

        def write_to_tmp():
            for line in input_stream:
                tmp.write(highlighter.highlight_line(line))
                tmp.flush()

        writer_thread = threading.Thread(target=write_to_tmp, daemon=True)
        writer_thread.start()

        pager_cmd = custom_pager or os.environ.get("TAILSPIN_PAGER") or "less -RS"
        if "[FILE]" in pager_cmd:
            pager_cmd = pager_cmd.replace("[FILE]", tmp_path)
        else:
            pager_cmd = f"{pager_cmd} {tmp_path}"

        subprocess.run(pager_cmd, shell=True)
        os.unlink(tmp_path)

if __name__ == "__main__":
    main()
