                content = s[i:end+1]
                next_part = s[end+1:].lstrip()
                if next_part.startswith(':'):
                    res += f"{DIM}{content}{RESET}"
                else:
                    inner = content[1:-1]
                    res += f"{DIM}\"{RESET}{self.apply_highlighters(inner)}{DIM}\"{RESET}"
