#!/usr/bin/env python3
import sys
import re
import os
import subprocess
import tempfile
import threading

RESET = "\033[0m"
DIM = "\033[2m"
ITALIC = "\033[3m"
RED = "\033[31m"
GREEN = "\033[32m"
YELLOW = "\033[33m"
BLUE = "\033[34m"
MAGENTA = "\033[35m"
CYAN = "\033[36m"
WHITE = "\033[37m"
BG_RED = "\033[41;30m"
BG_GREEN = "\033[42;30m"
BG_YELLOW = "\033[43;30m"
BG_MAGENTA = "\033[45;30m"

class Highlighter:
    def __init__(self, en=None, di=None, db=False, ch=None):
        self.gps = ["numbers", "urls", "pointers", "dates", "paths", "quotes", "key-value-pairs", "uuids", "ip-addresses", "processes", "json"]
        if en: self.en = en.split(",")
        elif di: self.en = [g for g in self.gps if g not in di.split(",")]
        else: self.en = self.gps
        self.db = db; self.ch = ch or []

    def highlight_line(self, line):
        if "json" in self.en and self.is_json(line): return self.h_json(line)
        return self.apply(line)

    def is_json(self, line):
        s = line.strip()
        return s.startswith('{') and s.endswith('}')

    def h_json(self, line):
        s = line.strip()
        s = re.sub(r'\{', '{ ', s); s = re.sub(r'\}', ' }', s)
        s = re.sub(r':', ': ', s); s = re.sub(r',', ', ', s)
        s = re.sub(r' +', ' ', s)
        res = ""; i = 0
        while i < len(s):
            if s[i] in '{}:,': res += f"{DIM}{s[i]}{RESET}"; i += 1
            elif s[i] == '"':
                end = s.find('"', i + 1)
                if end == -1: res += s[i:]; break
                content = s[i:end+1]
                next_part = s[end+1:].lstrip()
                if next_part.startswith(':'): res += f"{DIM}{content}{RESET}"
                else: res += f"{DIM}\"{RESET}{self.apply(content[1:-1])}{DIM}\"{RESET}"
                i = end + 1
            elif s[i].isspace(): res += s[i]; i += 1
            else:
                end = i
                while end < len(s) and s[end] not in ' {},:]:': end += 1
                res += self.apply(s[i:end]); i = end
        return res + "\n"

    def apply(self, line):
        ph = []
        def add(t): ph.append(t); return chr(0xE000 + len(ph) - 1)
        for cn, ws in self.ch:
            co = {"red": RED, "green": GREEN, "yellow": YELLOW, "blue": BLUE, "magenta": MAGENTA, "cyan": CYAN}.get(cn, "")
            for w in ws: line = re.sub(r'\b' + re.escape(w) + r'\b', lambda m: add(f"{co}{m.group(0)}{RESET}"), line)
        if "dates" in self.en:
            line = re.sub(r'\b(\d{2})([-/.])(\d{2})([-/.])(\d{4})\b', lambda m: add(f"{MAGENTA}{m.group(5)}{RESET}{DIM}{m.group(2)}{RESET}{MAGENTA}{m.group(1)}{RESET}{DIM}{m.group(4)}{RESET}{MAGENTA}{m.group(3)}{RESET}"), line)
            line = re.sub(r'\b(\d{4})([-/.])(\d{2})([-/.])(\d{2})\b', lambda m: add(f"{MAGENTA}{m.group(1)}{RESET}{DIM}{m.group(2)}{RESET}{MAGENTA}{m.group(3)}{RESET}{DIM}{m.group(4)}{RESET}{MAGENTA}{m.group(5)}{RESET}"), line)
        if "dates" in self.en or "numbers" in self.en:
            line = re.sub(r'\b(\d{2})(:)(\d{2})(:)(\d{2})([.,]\d+)?\b', lambda m: add(f"{BLUE}{m.group(1)}{RESET}{DIM}{m.group(2)}{RESET}{BLUE}{m.group(3)}{RESET}{DIM}{m.group(4)}{RESET}{BLUE}{m.group(5)}{RESET}" + (f"{DIM}{m.group(6)[0]}{RESET}{BLUE}{m.group(6)[1:]}{RESET}" if m.group(6) else "")), line)
        if "urls" in self.en:
            def h_url(m):
                s, d, p, q = m.groups()
                r = f"{DIM}{RED if s=='http' else GREEN}{s}{RESET}://{DIM}{BLUE}{d}{RESET}"
                if p:
                    for part in re.split(r'(/)', p):
                        if part == '/': r += f"{YELLOW}/{RESET}"
                        elif part: r += f"{BLUE}{part}{RESET}"
                if q:
                    qp = re.split(r'([\?&=])', q)
                    for j, qv in enumerate(qp):
                        if qv in '?&=': r += f"{RED}{qv}{RESET}"
                        elif j > 0 and qp[j-1] == '=': r += f"{CYAN}{qv}{RESET}"
                        else: r += f"{MAGENTA}{qv}{RESET}"
                return add(r)
            line = re.sub(r'\b(https?)://([^/ \n\?]+)(/[^ \n\?]*)?(\?[^ \n]*)?', h_url, line)
        def c_hex(text, is_ptr=False, group=False):
            r = ""
            if is_ptr and text.startswith("0x"): r += f"\033[3;34m0{RESET}{RED}x{RESET}"; text = text[2:]
            if group: parts = re.findall(r"\d+|[a-zA-Z]+|[.:-]", text)
            else: parts = text
            for c in parts:
                if c.isdigit(): r += f"\033[3;34m{c}{RESET}"
                elif c.isalpha(): r += f"\033[3;35m{c}{RESET}"
                else: r += f"{RED}{c}{RESET}"
            return r
        if "pointers" in self.en: line = re.sub(r'\b0x[0-9a-fA-F]+\b', lambda m: add(c_hex(m.group(0), True)), line)
        if "uuids" in self.en: line = re.sub(r'\b[0-9a-fA-F]{8}(-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}\b', lambda m: add(c_hex(m.group(0))), line)
        if "ip-addresses" in self.en:
            line = re.sub(r'\b\d{1,3}(\.\d{1,3}){3}\b', lambda m: add(c_hex(m.group(0), group=True)), line)
            line = re.sub(r'\b([0-9a-fA-F]{0,4}:){2,7}[0-9a-fA-F]{0,4}\b', lambda m: add(c_hex(m.group(0))), line)
        if "paths" in self.en:
            def hp(m):
                r = ""
                for part in re.split(r'(/)', m.group(0)):
                    if part == '/': r += f"{YELLOW}/{RESET}"
                    elif part == '~': r += f"{GREEN}~{RESET}"
                    elif part: r += f"{GREEN}{part}{RESET}"
                return add(r)
            line = re.sub(r'(?<= )(/[a-zA-Z0-9._-]+)+/?', hp, line)
            line = re.sub(r'\b(~(/[a-zA-Z0-9._-]+)+/?)\b', hp, line)
        if "processes" in self.en: line = re.sub(r'\b([a-zA-Z0-9._-]+)\[(\d+)\]', lambda m: add(f"{YELLOW}{m.group(1)}{RESET}{RED}[{RESET}{CYAN}{m.group(2)}{RESET}{RED}]{RESET}"), line)
        if "key-value-pairs" in self.en: line = re.sub(r'\b(\w+)(=)', lambda m: add(f"{DIM}{m.group(1)}{RESET}{WHITE}{m.group(2)}{RESET}"), line)
        if "quotes" in self.en: line = re.sub(r'".*?"', lambda m: add(f"{YELLOW}{m.group(0)}{RESET}"), line)
        if not self.db:
            line = re.sub(r'\b(true|false|null)\b', lambda m: add(f"\033[3;31m{m.group(0)}{RESET}"), line)
            line = re.sub(r'\b(INFO|SUCCESS)\b', lambda m: add(f"{WHITE}{m.group(0)}{RESET}"), line)
            line = re.sub(r'\b(DEBUG)\b', lambda m: add(f"{GREEN}{m.group(0)}{RESET}"), line)
            line = re.sub(r'\b(WARN)\b', lambda m: add(f"{YELLOW}{m.group(0)}{RESET}"), line)
            line = re.sub(r'\b(ERROR)\b', lambda m: add(f"{RED}{m.group(0)}{RESET}"), line)
            line = re.sub(r'\b(TRACE)\b', lambda m: add(f"{DIM}{m.group(0)}{RESET}"), line)
            for v, c in [("GET", BG_GREEN), ("POST", BG_YELLOW), ("PUT", BG_MAGENTA), ("PATCH", BG_MAGENTA), ("DELETE", BG_RED)]:
                line = re.sub(r'\b' + v + r'\b', lambda m: add(f"{c} {m.group(0)} {RESET}"), line)
        if "numbers" in self.en: line = re.sub(r'\b(\d+(\.\d+)?)\b', lambda m: add(f"{CYAN}{m.group(1)}{RESET}"), line)
        if "dates" in self.en:
            line = re.sub(r'(?<=[\uE000-\uF8FF])([ T])(?=[\uE000-\uF8FF])', lambda m: add(f"{RED}{m.group(1)}{RESET}"), line)
            line = re.sub(r'(?<=[\uE000-\uF8FF])(Z)\b', lambda m: add(f"{RED}{m.group(1)}{RESET}"), line)
        for i, p in enumerate(ph): line = line.replace(chr(0xE000 + i), p)
        return line

def run_pager(stream, hi, cp):
    with tempfile.NamedTemporaryFile(mode="w", delete=False) as tmp:
        tp = tmp.name
        def w():
            for l in stream: tmp.write(hi.highlight_line(l)); tmp.flush()
        threading.Thread(target=w, daemon=True).start()
        p = cp or os.environ.get("TAILSPIN_PAGER") or "less -RS"
        subprocess.run(p.replace("[FILE]", tp) if "[FILE]" in p else f"{p} {tp}", shell=True)
        os.unlink(tp)

