    parser.add_argument("f", nargs="*", metavar="FILE")
    parser.add_argument("-f", "--follow", action="store_true")
    parser.add_argument("-p", "--print", action="store_true")
    parser.add_argument("-e", "--exec", metavar="EXEC")
    parser.add_argument("--config-path", metavar="CONFIG_PATH")
    parser.add_argument("--highlight", action="append", metavar="COLOR_WORD")
    parser.add_argument("--enable", metavar="ENABLED_HIGHLIGHTERS")
    parser.add_argument("--disable", metavar="DISABLED_HIGHLIGHTERS")
    parser.add_argument("--disable-builtin-keywords", action="store_true")
    parser.add_argument("--pager", metavar="PAGER")
    parser.add_argument("-h", "--help", action="help")
    parser.add_argument("-V", "--version", action="version", version="tailspin 5.4.5")
    args = parser.parse_args()
    ch = []
    if args.highlight:
        for h in args.highlight:
            c, w = h.split(":", 1); ch.append((c, w.split(",")))
    hi = Highlighter(en=args.enable, di=args.disable, db=args.disable_builtin_keywords, ch=ch)
    if args.exec:
        p = subprocess.Popen(args.exec, shell=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
        if args.print:
            for l in p.stdout: print(hi.highlight_line(l), end="")
        else: run_pager(p.stdout, hi, args.pager)
    elif not args.f:
        if not sys.stdin.isatty():
            for l in sys.stdin: print(hi.highlight_line(l), end="")
        else: parser.print_help()
    else:
        if args.follow:
            p = subprocess.Popen(["tail", "-f", args.f[0]], stdout=subprocess.PIPE, text=True)
            if args.print:
                for l in p.stdout: print(hi.highlight_line(l), end="")
            else: run_pager(p.stdout, hi, args.pager)
        else:
            def st():
                for f in args.f:
                    with open(f, "r") as fd:
                        for l in fd: yield l
            if args.print or not sys.stdout.isatty():
                for l in st(): print(hi.highlight_line(l), end="")
            else: run_pager(st(), hi, args.pager)
